def solution(text: str) -> str:
    """Returns the string with each alphabetic character shifted to the next one in the alphabet (z→a, Z→A), leaving non-alphabetic characters unchanged."""
    result = []
    for c in text:
        if c == 'z':
            result.append('a')
        elif c == 'Z':
            result.append('A')
        elif 'a' <= c < 'z' or 'A' <= c < 'Z':
            result.append(chr(ord(c) + 1))
        else:
            result.append(c)
    return ''.join(result)
